import { resolveSubstrateGap, type SubstrateGap } from "./substrate-gap.js";

export interface GapCountPointer {
  status?: SubstrateGap["status"];
  category?: string;
}

export async function resolveGapCount(pointer: GapCountPointer = {}): Promise<{
  shape: "gapCount";
  body: { count: number; status: string; category?: string };
}> {
  const status = (pointer.status ?? "open") as SubstrateGap["status"];
  const res = (await resolveSubstrateGap({
    type: "substrateGap",
    status,
    ...(pointer.category ? { category: pointer.category as never } : {}),
    limit: Number.MAX_SAFE_INTEGER,
  })) as { body?: { gaps?: unknown } };
  const gaps = res?.body?.gaps;
  return {
    shape: "gapCount",
    body: {
      count: Array.isArray(gaps) ? gaps.length : 0,
      status: String(status),
      ...(pointer.category ? { category: pointer.category } : {}),
    },
  };
}

